const PosDB=function(){const VERSION=1;let db=null;let dbName="";function req(r){return new Promise((resolve,reject)=>{r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}function open(ownerId){const name="mwakete-pos-"+String(ownerId||"unknown").replace(/[^A-Za-z0-9_-]/g,"");if(db&&dbName===name)return Promise.resolve(db);if(db){db.close();db=null}if(!("indexedDB"in window))return Promise.reject(new Error("This browser cannot store sales offline."));return new Promise((resolve,reject)=>{const r=indexedDB.open(name,VERSION);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains("items"))d.createObjectStore("items",{keyPath:"variantId"});if(!d.objectStoreNames.contains("queue"))d.createObjectStore("queue",{keyPath:"clientTxnId"});if(!d.objectStoreNames.contains("sales")){const s=d.createObjectStore("sales",{keyPath:"clientTxnId"});s.createIndex("at","at")}if(!d.objectStoreNames.contains("meta"))d.createObjectStore("meta",{keyPath:"key"});if(!d.objectStoreNames.contains("log"))d.createObjectStore("log",{keyPath:"id",autoIncrement:true})};r.onsuccess=()=>{db=r.result;dbName=name;db.onversionchange=()=>{db.close();db=null};resolve(db)};r.onerror=()=>reject(r.error||new Error("Could not open the till storage."));r.onblocked=()=>reject(new Error("Close other Mwakete POS tabs and try again."))})}function tx(stores,mode,work){return new Promise((resolve,reject)=>{const t=db.transaction(stores,mode);let out;t.oncomplete=()=>resolve(out);t.onerror=()=>reject(t.error||new Error("Could not save on this device."));t.onabort=()=>reject(t.error||new Error("Saving on this device was stopped."));Promise.resolve(work(t)).then(v=>{out=v},e=>{try{t.abort()}catch(x){}reject(e)})})}const all=store=>tx([store],"readonly",t=>req(t.objectStore(store).getAll()));const get=(store,key)=>tx([store],"readonly",t=>req(t.objectStore(store).get(key)));const put=(store,value)=>tx([store],"readwrite",t=>{t.objectStore(store).put(value)});const del=(store,key)=>tx([store],"readwrite",t=>{t.objectStore(store).delete(key)});async function getMeta(key,fallback){const row=await get("meta",key);return row?row.value:fallback}const setMeta=(key,value)=>put("meta",{key:key,value:value});function replaceCatalog(items,cursor,extraMeta){return tx(["items","meta","queue"],"readwrite",async t=>{const pending={};(await req(t.objectStore("queue").getAll())).forEach(e=>(e.local&&e.local.lines||[]).forEach(l=>{pending[l.variantId]=(pending[l.variantId]||0)+Number(l.qty)}));const st=t.objectStore("items");st.clear();items.forEach(i=>{i.localSold=pending[i.variantId]||0;if(i.tracked&&i.available!==null&&i.available!==undefined)i.available=Math.max(0,Number(i.available)-i.localSold);st.put(i)});const m=t.objectStore("meta");m.put({key:"cursor",value:cursor});m.put({key:"catalogAt",value:(new Date).toISOString()});Object.keys(extraMeta||{}).forEach(k=>m.put({key:k,value:extraMeta[k]}))})}function upsertItems(items,removeProductIds){return tx(["items"],"readwrite",async t=>{const st=t.objectStore("items");const keep={};(await req(st.getAll())).forEach(i=>{keep[i.variantId]=Number(i.localSold||0)});items.forEach(i=>{i.localSold=keep[i.variantId]||0;if(i.tracked&&i.available!==null&&i.available!==undefined)i.available=Math.max(0,Number(i.available)-i.localSold)});if(removeProductIds&&removeProductIds.length){const existing=await req(st.getAll());existing.filter(i=>removeProductIds.indexOf(String(i.productId))!==-1).forEach(i=>st.delete(i.variantId))}items.forEach(i=>st.put(i))})}function applyStockChanges(changes,newCursor){return tx(["items","meta"],"readwrite",async t=>{const st=t.objectStore("items");for(const c of changes){if(c.kind!=="stock"||!c.variantId)continue;const it=await req(st.get(c.variantId));if(!it)continue;if(c.stock!==undefined)it.stock=c.stock;if(c.reserved!==undefined)it.reserved=c.reserved;if(it.tracked&&it.stock!==null&&it.stock!==undefined)it.available=Math.max(0,Number(it.stock)-Number(it.reserved||0)-Number(it.localSold||0));st.put(it)}t.objectStore("meta").put({key:"cursor",value:newCursor})})}function saveSaleLocally(entry,stockDeltas){return tx(["queue","sales","items"],"readwrite",async t=>{t.objectStore("queue").put(entry);t.objectStore("sales").put({clientTxnId:entry.clientTxnId,at:entry.createdAt,state:entry.state,local:entry.local,server:null});const st=t.objectStore("items");for(const d of stockDeltas||[]){const it=await req(st.get(d.variantId));if(!it||!it.tracked)continue;it.available=Math.max(0,Number(it.available||0)-d.qty);it.localSold=Number(it.localSold||0)+d.qty;st.put(it)}})}function settleQueued(clientTxnId,state,server){return tx(["queue","sales","items"],"readwrite",async t=>{const q=t.objectStore("queue");const entry=await req(q.get(clientTxnId));if(state==="synced"){q.delete(clientTxnId);const st=t.objectStore("items");for(const l of entry&&entry.local&&entry.local.lines||[]){const it=await req(st.get(l.variantId));if(!it||!it.localSold)continue;it.localSold=Math.max(0,Number(it.localSold)-Number(l.qty));st.put(it)}}else if(entry){entry.state=state;entry.server=server||entry.server;q.put(entry)}const s=t.objectStore("sales");const row=await req(s.get(clientTxnId))||{clientTxnId:clientTxnId,at:(new Date).toISOString(),local:entry?entry.local:null};row.state=state;if(server)row.server=server;s.put(row)})}async function addLog(kind,message,extra){try{await put("log",{at:(new Date).toISOString(),kind:kind,message:String(message||"").slice(0,300),extra:extra||null});const rows=await all("log");if(rows.length>200)await tx(["log"],"readwrite",t=>{rows.slice(0,rows.length-200).forEach(r=>t.objectStore("log").delete(r.id))})}catch(e){}}async function askPersistent(){try{return navigator.storage&&navigator.storage.persist?await navigator.storage.persist():false}catch(e){return false}}return{open:open,all:all,get:get,put:put,del:del,getMeta:getMeta,setMeta:setMeta,replaceCatalog:replaceCatalog,upsertItems:upsertItems,applyStockChanges:applyStockChanges,saveSaleLocally:saveSaleLocally,settleQueued:settleQueued,addLog:addLog,askPersistent:askPersistent,name:()=>dbName}}();